def to_roman(n):
    """Convert an integer (1..3999) to a Roman numeral string."""
    if not isinstance(n, int) or isinstance(n, bool):
        raise ValueError(f"expected int, got {type(n).__name__}")
    if n < 1 or n > 3999:
        raise ValueError(f"n must be between 1 and 3999, got {n}")

    values = [
        (1000, "M"), (900, "CM"), (500, "D"), (400, "CD"),
        (100, "C"), (90, "XC"), (50, "L"), (40, "XL"),
        (10, "X"), (9, "IX"), (5, "V"), (4, "IV"), (1, "I"),
    ]
    result = []
    for val, sym in values:
        while n >= val:
            result.append(sym)
            n -= val
    return "".join(result)


def from_roman(s):
    """Convert a standard subtractive Roman numeral string to an integer."""
    if not isinstance(s, str):
        raise ValueError(f"expected str, got {type(s).__name__}")
    if not s:
        raise ValueError("empty string")

    roman_values = {
        "I": 1, "V": 5, "X": 10, "L": 50,
        "C": 100, "D": 500, "M": 1000,
    }

    # Validate characters
    for ch in s:
        if ch not in roman_values:
            raise ValueError(f"invalid character '{ch}'")

    # Parse values
    nums = [roman_values[ch] for ch in s]

    # Basic validity: total must be positive
    total = 0
    for i in range(len(nums)):
        if i + 1 < len(nums) and nums[i] < nums[i + 1]:
            total -= nums[i]
        else:
            total += nums[i]

    if total <= 0:
        raise ValueError("invalid numeral")

    # Re-encode to verify it round-trips (catches IIII, VV, IC, XM, etc.)
    if to_roman(total) != s:
        raise ValueError(f"{s} is not a well-formed Roman numeral")

    return total

import pytest

from roman import to_roman, from_roman


class TestToRoman:
    """Tests for to_roman(n)."""

    def test_one(self):
        assert to_roman(1) == "I"

    def test_two(self):
        assert to_roman(2) == "II"

    def test_three(self):
        assert to_roman(3) == "III"

    def test_four(self):
        assert to_roman(4) == "IV"

    def test_five(self):
        assert to_roman(5) == "V"

    def test_nine(self):
        assert to_roman(9) == "IX"

    def test_forty(self):
        assert to_roman(40) == "XL"

    def test_forty_nine(self):
        assert to_roman(49) == "XLIX"

    def test_fifty(self):
        assert to_roman(50) == "L"

    def test_hundred(self):
        assert to_roman(100) == "C"

    def test_hundred_ninety_nine(self):
        assert to_roman(199) == "CXCIX"

    def test_five_hundred(self):
        assert to_roman(500) == "D"

    def test_five_hundred_ninety_nine(self):
        assert to_roman(599) == "DXCIX"

    def test_thousand(self):
        assert to_roman(1000) == "M"

    def test_two_thousand(self):
        assert to_roman(2000) == "MM"

    def test_two_thousand_ninety_nine(self):
        assert to_roman(2099) == "MMXCIX"

    def test_three_thousand(self):
        assert to_roman(3000) == "MMM"

    def test_max_value(self):
        assert to_roman(3999) == "MMMCMXCIX"

    @pytest.mark.parametrize("n", [0, -1, -42, 4000, 10000])
    def test_out_of_range(self, n):
        with pytest.raises(ValueError):
            to_roman(n)

    @pytest.mark.parametrize("val", [1.5, "I", True, None, 3.14])
    def test_non_integer(self, val):
        with pytest.raises(ValueError):
            to_roman(val)


class TestFromRoman:
    """Tests for from_roman(s)."""

    def test_i(self):
        assert from_roman("I") == 1

    def test_ii(self):
        assert from_roman("II") == 2

    def test_iii(self):
        assert from_roman("III") == 3

    def test_iv(self):
        assert from_roman("IV") == 4

    def test_v(self):
        assert from_roman("V") == 5

    def test_ix(self):
        assert from_roman("IX") == 9

    def test_xl(self):
        assert from_roman("XL") == 40

    def test_xlix(self):
        assert from_roman("XLIX") == 49

    def test_l(self):
        assert from_roman("L") == 50

    def test_c(self):
        assert from_roman("C") == 100

    def test_cxcix(self):
        assert from_roman("CXCIX") == 199

    def test_d(self):
        assert from_roman("D") == 500

    def test_dxcix(self):
        assert from_roman("DXCIX") == 599

    def test_m(self):
        assert from_roman("M") == 1000

    def test_mmcxcix(self):
        assert from_roman("MMXCIX") == 2099

    def test_mmmcmxcix(self):
        assert from_roman("MMMCMXCIX") == 3999

    # --- Invalid numerals ---

    def test_empty_string(self):
        with pytest.raises(ValueError):
            from_roman("")

    @pytest.mark.parametrize("s", ["IIII", "VV", "LL", "CC", "DD", "MM"])
    def test_repeated_nonsubtractive(self, s):
        with pytest.raises(ValueError):
            from_roman(s)

    @pytest.mark.parametrize("s", ["IC", "XM", "IL", "XD", "IX", "IM"])
    def test_invalid_subtractive_pairs(self, s):
        with pytest.raises(ValueError):
            from_roman(s)

    def test_banana(self):
        with pytest.raises(ValueError):
            from_roman("banana")

    def test_null(self):
        with pytest.raises(ValueError):
            from_roman(None)

    def test_float_input(self):
        with pytest.raises(ValueError):
            from_roman(3.14)

    def test_boolean_input(self):
        with pytest.raises(ValueError):
            from_roman(True)

    def test_negative_numeral(self):
        with pytest.raises(ValueError):
            from_roman("-I")

    def test_mmmm(self):
        with pytest.raises(ValueError):
            from_roman("MMMM")


class TestRoundTrip:
    """Verify from_roman(to_roman(n)) == n for every valid n."""

    @pytest.mark.parametrize("n", range(1, 4000))
    def test_round_trip(self, n):
        assert from_roman(to_roman(n)) == n

